describe('getReadinessNumber', () => {
  it('returns the numeric value for a valid string', () => {
    expect(getReadinessNumber('7')).toBe(7);
  });
  it('returns 0 for non-numeric input', () => {
    expect(getReadinessNumber('abc')).toBe(0);
    expect(getReadinessNumber('')).toBe(0);
  });
});

describe('isFatigueWatch', () => {
  it('returns true for scores at or below 5', () => {
    expect(isFatigueWatch('5')).toBe(true);
    expect(isFatigueWatch('1')).toBe(true);
  });
  it('returns false for scores above 5', () => {
    expect(isFatigueWatch('6')).toBe(false);
  });
  it('returns false for non-numeric input', () => {
    expect(isFatigueWatch('abc')).toBe(false);
  });
});

describe('getReadinessLabel', () => {
  it('returns correct label for each band', () => {
    expect(getReadinessLabel('2')).toBe('Low');
    expect(getReadinessLabel('4')).toBe('Fatigue Watch');
    expect(getReadinessLabel('6')).toBe('Moderate');
    expect(getReadinessLabel('9')).toBe('High');
    expect(getReadinessLabel('abc')).toBe('Unknown');
  });
});

describe('getNotesQualityMessage', () => {
  it('returns empty string for a quality note', () => {
    expect(getNotesQualityMessage('Steady effort, breathing controlled, no pain.')).toBe('');
  });
  it('returns missing notes for empty input', () => {
    expect(getNotesQualityMessage('')).toBe('missing notes');
    expect(getNotesQualityMessage('   ')).toBe('missing notes');
  });
  it('returns notes too brief for single weak words', () => {
    expect(getNotesQualityMessage('good')).toBe('notes too brief');
    expect(getNotesQualityMessage('OK')).toBe('notes too brief'); // case-insensitive
  });
  it('returns notes need more detail for short but non-blacklisted notes', () => {
    expect(getNotesQualityMessage('felt tired')).toBe('notes need more detail');
  });
});

describe('getNotesQualityWarning', () => {
  it('returns empty string for quality notes', () => {
    expect(getNotesQualityWarning('Steady effort, breathing controlled, no pain.')).toBe('');
  });
  it('returns add-a-note message for empty notes', () => {
    expect(getNotesQualityWarning('')).toContain('Add a short note');
  });
  it('returns brief-note message for weak-word notes', () => {
    expect(getNotesQualityWarning('done')).toContain('too brief');
  });
  it('returns more-detail message for short notes', () => {
    expect(getNotesQualityWarning('felt tired')).toContain('one more useful detail');
  });
});

describe('getNoteStarter', () => {
  it('returns a ruck-specific starter for Ruck category', () => {
    expect(getNoteStarter('Ruck')).toContain('Ruck notes');
  });
  it('returns a run-specific starter for Run category', () => {
    expect(getNoteStarter('Run')).toContain('Run notes');
  });
  it('returns the generic fallback for Mobility', () => {
    expect(getNoteStarter('Mobility')).toContain('Session notes');
  });
});

describe('getTrainingLogHealthLabel and getTrainingLogHealthMessage', () => {
  it('labels scores correctly', () => {
    expect(getTrainingLogHealthLabel(90)).toBe('Excellent');
    expect(getTrainingLogHealthLabel(75)).toBe('Healthy');
    expect(getTrainingLogHealthLabel(55)).toBe('Needs Work');
    expect(getTrainingLogHealthLabel(30)).toBe('Poor Data');
  });
  it('messages match label bands', () => {
    expect(getTrainingLogHealthMessage(90)).toContain('strong enough');
    expect(getTrainingLogHealthMessage(30)).toContain('too weak');
  });
});

describe('calculateTrainingLogHealthScore edge cases', () => {
  it('returns 0 for empty logs', () => {
    expect(calculateTrainingLogHealthScore([])).toBe(0);
  });
  it('returns high score for all strong logs', () => {
    const score = calculateTrainingLogHealthScore([
      makeLog({ readiness: '9' }),
      makeLog({ readiness: '8' }),
    ]);
    expect(score).toBeGreaterThanOrEqual(80);
  });
});

describe('readiness trend edge cases', () => {
  it('returns neutral with no data for empty logs', () => {
    expect(buildReadinessTrend([])).toMatchObject({ status: 'neutral', label: 'No Data' });
  });
  it('returns baseline for a single log', () => {
    expect(buildReadinessTrend([makeLog({ readiness: '7' })])).toMatchObject({
      status: 'neutral',
      label: 'Baseline',
      latest: 7,
    });
  });
  it('returns stable when change is within -1 to +1', () => {
    expect(
      buildReadinessTrend([
        makeLog({ id: 1, date: '2026-05-10', readiness: '7' }),
        makeLog({ id: 2, date: '2026-05-11', readiness: '8' }),
      ])
    ).toMatchObject({ status: 'neutral', label: 'Stable' });
  });
});

describe('buildNextWeekRecommendation', () => {
  it('suggests 3-4 sessions when no sessions logged this week', () => {
    const thisWeek = buildWeekSummary([], 0);
    const lastWeek = buildWeekSummary([], 1);
    expect(buildNextWeekRecommendation(thisWeek, lastWeek)).toContain('3 to 4 sessions');
  });

  it('recommends recovery when fatigue watch sessions >= 2', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-05-14T12:00:00Z'));
    const thisWeek = buildWeekSummary([
      makeLog({ id: 1, date: '2026-05-12', readiness: '4' }),
      makeLog({ id: 2, date: '2026-05-13', readiness: '3' }),
    ], 0);
    const lastWeek = buildWeekSummary([], 1);
    expect(buildNextWeekRecommendation(thisWeek, lastWeek)).toContain('recovery');
  });

  it('recommends holding load when readiness drops vs last week', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-05-14T12:00:00Z'));
    const thisWeek = buildWeekSummary([makeLog({ id: 1, date: '2026-05-12', readiness: '5' })], 0);
    const lastWeek = buildWeekSummary([makeLog({ id: 1, date: '2026-05-05', readiness: '8' })], 1);
    expect(buildNextWeekRecommendation(thisWeek, lastWeek)).toContain('Hold');
  });
});

describe('buildWeekPlan plan types', () => {
  it('returns a progressive plan when trend is improving and sessions are consistent', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-05-14T12:00:00Z'));
    const plan = buildWeekPlan([
      makeLog({ id: 1, date: '2026-05-08', readiness: '6' }),
      makeLog({ id: 2, date: '2026-05-11', readiness: '8' }),
      makeLog({ id: 3, date: '2026-05-12', readiness: '8' }),
      makeLog({ id: 4, date: '2026-05-13', readiness: '9' }),
    ]);
    expect(plan.planType).toBe('progressive');
    expect(plan.days).toHaveLength(7);
  });

  it('returns a standard plan for stable readiness', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-05-14T12:00:00Z'));
    const plan = buildWeekPlan([
      makeLog({ id: 1, date: '2026-05-12', readiness: '7' }),
      makeLog({ id: 2, date: '2026-05-13', readiness: '7' }),
    ]);
    expect(plan.planType).toBe('standard');
  });
});

describe('filterAndSortLogs', () => {
  it('returns all logs when filter is All and no search query', () => {
    const logs = [
      makeLog({ id: 1, category: 'Ruck' }),
      makeLog({ id: 2, category: 'Run' }),
    ];
    expect(filterAndSortLogs(logs, 'All', '', 'Newest', false)).toHaveLength(2);
  });

  it('sorts by oldest first', () => {
    const sorted = filterAndSortLogs(
      [
        makeLog({ id: 1, date: '2026-05-12' }),
        makeLog({ id: 2, date: '2026-05-10' }),
      ],
      'All', '', 'Oldest', false
    );
    expect(sorted[0].date).toBe('2026-05-10');
  });

  it('sorts by lowest readiness first', () => {
    const sorted = filterAndSortLogs(
      [
        makeLog({ id: 1, readiness: '8' }),
        makeLog({ id: 2, readiness: '4' }),
      ],
      'All', '', 'Lowest Readiness', false
    );
    expect(sorted[0].readiness).toBe('4');
  });

  it('filters to weak logs only when showWeakLogsOnly is true', () => {
    const logs = [
      makeLog({ id: 1, notes: 'ok' }), // weak
      makeLog({ id: 2 }),               // good
    ];
    const result = filterAndSortLogs(logs, 'All', '', 'Newest', true);
    expect(result).toHaveLength(1);
    expect(result[0].id).toBe(1);
  });
});
