```ts
describe('buildWeeklyReport edge cases', () => {
  it('handles empty logs gracefully', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-05-14T12:00:00Z'));

    const report = buildWeeklyReport([]);
    expect(report.text).toContain('No recent sessions logged.');
    expect(report.text).toContain('No key notes available.');
    expect(report.text).toContain('Total Logs: 0');
  });

  it('uses the now parameter to set generatedAt', () => {
    const report = buildWeeklyReport([], new Date('2026-01-15T00:00:00Z'));
    expect(report.generatedAt).toBe('2026-01-15');
  });

  it('shows up to 3 key notes from the most recent logs', () => {
    const report = buildWeeklyReport([
      makeLog({ id: 1, date: '2026-05-11', notes: 'First detailed note about session effort and fatigue levels.' }),
      makeLog({ id: 2, date: '2026-05-12', notes: 'Second detailed note about breathing and posture control.' }),
      makeLog({ id: 3, date: '2026-05-13', notes: 'Third detailed note about pack weight and hot spots.' }),
      makeLog({ id: 4, date: '2026-05-14', notes: 'Fourth note that should not appear in key notes section.' }),
    ], new Date('2026-05-15T00:00:00Z'));

    const keyNotesIndex = report.text.indexOf('KEY NOTES');
    const keyNotesSection = report.text.slice(keyNotesIndex);
    // Only 3 notes should appear
    expect((keyNotesSection.match(/\d{4}-\d{2}-\d{2}/g) ?? []).length).toBeLessThanOrEqual(3);
  });

  it('omits notes for logs with empty notes field', () => {
    const report = buildWeeklyReport([
      makeLog({ id: 1, date: '2026-05-11', notes: '' }),
    ], new Date('2026-05-15T00:00:00Z'));
    expect(report.text).toContain('No key notes available.');
  });
});
